def cosine(a,b):
    import math
    if len(a)!=len(b): raise ValueError('dimensions')
    na=math.sqrt(sum(x*x for x in a));nb=math.sqrt(sum(x*x for x in b))
    return sum(x*y for x,y in zip(a,b))/(na*nb) if na and nb else 0

